// Folds the program's answers into parity.json: [{ id, input, program }] where program is "ok" or the program's error,
// as answered by the wrapper .so built from rc23 178fedc4.
// Usage: tsx test/fixtures/v22-bsl/merge-results.ts <rows.json> <results.json> <so-md5> <out parity.json>
import fs from "node:fs";

const [rowsPath, resultsPath, soMd5, out] = process.argv.slice(2) as [string, string, string, string];
const rows = JSON.parse(fs.readFileSync(rowsPath, "utf8")) as { id: string; input: unknown }[];
const answers = new Map((JSON.parse(fs.readFileSync(resultsPath, "utf8")) as { id: string; result: string }[]).map((r) => [r.id, r.result]));
const merged = rows.map((r) => {
  const program = answers.get(r.id);
  if (program === undefined) throw new Error(`no program answer for ${r.id}`);
  return { id: r.id, input: r.input, program };
});
fs.writeFileSync(out, JSON.stringify({
  _comment: `Band Safety Law parity rows: InitMarket sent to the real wrapper .so in LiteSVM (percolator-prog branch bsl6/initmarket-matrix, tests/bsl6_initmarket_matrix.rs). program = rc23 178fedc4 (.so md5 ${soMd5}, cargo build-sbf --features devnet, engine 2f05df8c). Generated by gen-rows.ts + merge-results.ts.`,
  rows: merged,
}));
console.log(`${merged.length} rows -> ${out}`);
